// Generated by `raea-motion types` from raea-native's registry (every host's calls); don't edit by hand.
// native(name, args) is typed by this table: a call that isn't registered, or wrong arguments, fails to check.

export interface NativeCalls {
  /** a packet decoded to planar f32, base64 */
  "adec.decode": { args: { id: number; data: string }; answer: { rate: number; channels: number; frames: number; data: string } };
  /** drop a decoder */
  "adec.free": { args: { id: number }; answer: null };
  /** a Symphonia decoder for aac, mp3 or flac */
  "adec.new": { args: { codec: string; description: string; rate: number; channels: number }; answer: { id: number } };
  /** planar f32 samples (base64, channel after channel) encoded; the packets they complete */
  "aenc.encode": { args: { id: number; data: string; channels: number }; answer: { packets: { data: string; pts: number; dur: number }[] } };
  /** the encoder flushed */
  "aenc.finish": { args: { id: number }; answer: { packets: { data: string; pts: number; dur: number }[] } };
  /** drop an encoder */
  "aenc.free": { args: { id: number }; answer: null };
  /** an AAC-LC encoder (AudioToolbox): its AudioSpecificConfig (base64) and its priming in frames */
  "aenc.new": { args: { rate: number; channels: number; kbps?: number }; answer: { id: number; description: string; priming: number } };
  /** agent-browser's command line words run in process (Chrome over CDP, or --engine blitz: raea's own engine): the response and the printed text */
  "browser.run": { args: { args: string[] }; answer: { success: boolean; data: unknown; error: string | null; code: string | null; text: string } };
  /** raea-motion's command line (render, bundle, types), run in process in cwd */
  "cli.raea-motion": { args: { args: string[]; cwd: string }; answer: { exit: number; stdout: string; stderr: string } };
  /** rdb's command line (media verbs too: rdb media, rdb ffmpeg), run in process in cwd */
  "cli.rdb": { args: { args: string[]; cwd: string }; answer: { exit: number; stdout: string; stderr: string } };
  /** a headless run ends with this exit code */
  "done": { args: { code: number }; answer: null };
  /** an entity's children */
  "ecs.children": { args: { world: number; id: number }; answer: number[] };
  /** the frame's events cleared (each step starts with none) */
  "ecs.clear_events": { args: { world: number }; answer: null };
  /** a copy of a world */
  "ecs.clone": { args: { world: number }; answer: { world: number } };
  /** one numeric column of a kind, in id order */
  "ecs.column": { args: { world: number; kind: string; col: string }; answer: (number | null)[] };
  /** an entity's components by name */
  "ecs.components": { args: { world: number; id: number }; answer: Record<string, unknown> };
  /** how many entities of a kind */
  "ecs.count": { args: { world: number; kind: string }; answer: number };
  /** remove an entity and its children */
  "ecs.despawn": { args: { world: number; id: number }; answer: null };
  /** this frame's events of a name */
  "ecs.events": { args: { world: number; name: string }; answer: unknown[] };
  /** entities with every `with` component and no `without` one (Bevy's query), passing every condition ("Comp.field") */
  "ecs.find": { args: { world: number; with?: string[]; without?: string[]; where?: [string, "==" | "!=" | "<" | "<=" | ">" | ">=", number | string | boolean][]; rows?: boolean }; answer: { ids: number[]; rows?: { id: number; components: Record<string, unknown> }[] } };
  /** drop a world */
  "ecs.free": { args: { world: number }; answer: null };
  /** an entity's row (its kind's columns) */
  "ecs.get": { args: { world: number; id: number }; answer: { id: number; kind: string } & Record<string, number | string | boolean> };
  /** components added to (or replaced on) an entity */
  "ecs.insert": { args: { world: number; id: number; components: Record<string, unknown> }; answer: null };
  /** a new world (Bevy's) */
  "ecs.new": { args: {}; answer: { world: number } };
  /** an entity's parent (set it with parent; null clears it) */
  "ecs.parent": { args: { world: number; id: number; parent?: number | null }; answer: number | null };
  /** ids of kind's entities passing every condition */
  "ecs.query": { args: { world: number; kind: string; where: [string, "==" | "!=" | "<" | "<=" | ">" | ">=", number | string | boolean][] }; answer: { ids: number[] } };
  /** components taken off an entity */
  "ecs.remove": { args: { world: number; id: number; names: string[] }; answer: null };
  /** a resource (set it with value) */
  "ecs.resource": { args: { world: number; name: string; value?: unknown }; answer: unknown };
  /** every kind's rows, by kind then id */
  "ecs.rows": { args: { world: number }; answer: ({ id: number; kind: string } & Record<string, number | string | boolean>)[] };
  /** the world's Mesh+Transform entities (world space) and lights, to draw */
  "ecs.scene": { args: { world: number }; answer: { id: number; kind: "Mesh" | "Light"; mesh?: unknown; light?: unknown; position?: [number, number, number]; rotation?: [number, number, number]; scale?: number }[] };
  /** an event for this frame */
  "ecs.send": { args: { world: number; name: string; value?: unknown }; answer: null };
  /** columns merged into an entity's kind */
  "ecs.set": { args: { world: number; id: number; cols: Record<string, number | string | boolean> }; answer: null };
  /** a new entity: a kind with columns, and/or any components */
  "ecs.spawn": { args: { world: number; kind?: string; cols?: Record<string, number | string | boolean>; components?: Record<string, unknown>; parent?: number }; answer: { id: number } };
  /** drop an engine frame */
  "frame.free": { args: { frame: number }; answer: null };
  /** an engine frame's size */
  "frame.info": { args: { frame: number }; answer: { width: number; height: number } };
  /** an engine frame written as PNG */
  "frame.png": { args: { frame: number; path: string }; answer: null };
  /** an engine frame scaled (a new frame) */
  "frame.scale": { args: { frame: number; width: number; height: number }; answer: { frame: number; width: number; height: number } };
  /** an engine frame rotated, flipped, cropped and resized (a new frame): mediabunny's transformations, natively */
  "frame.transform": { args: { frame: number; rotation?: number; flip?: boolean; crop?: { left: number; top: number; width: number; height: number }; width: number; height: number; fit?: "fill" | "contain" | "cover" }; answer: { frame: number; width: number; height: number } };
  /** a command starts: what follows is its row */
  "fs.begin": { args: { id: number; cmd: string }; answer: null };
  /** a path's mode set */
  "fs.chmod": { args: { id: number; path: string; mode: number }; answer: null };
  /** a file (or with recursive, a folder) copied */
  "fs.cp": { args: { id: number; src: string; dest: string; recursive?: boolean }; answer: null };
  /** the command ends: its action row */
  "fs.end": { args: { id: number; exit?: number; error?: string }; answer: Record<string, unknown> | null };
  /** whether a path is there (links followed) */
  "fs.exists": { args: { id: number; path: string }; answer: boolean };
  /** a hard link made */
  "fs.link": { args: { id: number; existing: string; path: string }; answer: null };
  /** the project's action rows (the last n) */
  "fs.log": { args: { id: number; last?: number }; answer: Record<string, unknown>[] };
  /** a path's facts, a link itself */
  "fs.lstat": { args: { id: number; path: string }; answer: { isFile: boolean; isDirectory: boolean; isSymbolicLink: boolean; mode: number; size: number; mtimeMs: number } };
  /** a folder made */
  "fs.mkdir": { args: { id: number; path: string; recursive?: boolean; exclusive?: boolean; mode?: number }; answer: null };
  /** a path moved */
  "fs.mv": { args: { id: number; src: string; dest: string }; answer: null };
  /** a project folder opened as a filesystem (made if missing) */
  "fs.open": { args: { root: string }; answer: { id: number; root: string } };
  /** every path in the project (to a limit) */
  "fs.paths": { args: { id: number; limit?: number }; answer: string[] };
  /** a file's bytes, base64 */
  "fs.read": { args: { id: number; path: string }; answer: string };
  /** a folder's entries, by name */
  "fs.readdir": { args: { id: number; path: string }; answer: { name: string; isFile: boolean; isDirectory: boolean; isSymbolicLink: boolean }[] };
  /** a link's target (a project path when it points inside) */
  "fs.readlink": { args: { id: number; path: string }; answer: string };
  /** a path with every link followed */
  "fs.realpath": { args: { id: number; path: string }; answer: string };
  /** the last undone command's changes made again */
  "fs.redo": { args: { id: number }; answer: Record<string, unknown> | null };
  /** a file, link or folder removed */
  "fs.rm": { args: { id: number; path: string; recursive?: boolean; force?: boolean }; answer: null };
  /** a path's facts, links followed */
  "fs.stat": { args: { id: number; path: string }; answer: { isFile: boolean; isDirectory: boolean; isSymbolicLink: boolean; mode: number; size: number; mtimeMs: number } };
  /** a link made (an absolute target is a project path) */
  "fs.symlink": { args: { id: number; target: string; path: string }; answer: null };
  /** a path's state kept as it is now, before a tool outside the filesystem changes it (so the command's row has it, and undo can restore it) */
  "fs.touch": { args: { id: number; path: string }; answer: null };
  /** the last command's changes taken back (null when there's none) */
  "fs.undo": { args: { id: number }; answer: Record<string, unknown> | null };
  /** a path's modification time set */
  "fs.utimes": { args: { id: number; path: string; mtimeMs: number }; answer: null };
  /** bytes written (or appended) to a file */
  "fs.write": { args: { id: number; path: string; data: string; append?: boolean; exclusive?: boolean; mode?: number }; answer: null };
  /** an environment variable of the host process (null when unset) */
  "host.env": { args: { name: string }; answer: string | null };
  /** whether this host answers a native call */
  "host.has": { args: { name: string }; answer: boolean };
  /** the host's platform */
  "host.platform": { args: {}; answer: "macos" | "ios" | "linux" | "windows" | "other" };
  /** one line from the host process's stdin (null at its end): a JSON-lines server's next request */
  "host.readline": { args: {}; answer: string | null };
  /** text written to the host process's stdout, flushed: a JSON-lines server's reply */
  "host.write": { args: { text: string }; answer: null };
  /** HTML as Markdown (htmd: headings, lists, links, emphasis, code; scripts and styles dropped) */
  "html.markdown": { args: { html: string }; answer: string };
  /** JavaScript or TypeScript run as an ES module in a fresh isolate (imports only inside root, native calls only from allow) */
  "js.run": { args: { root: string; cwd: string; file?: string; code?: string; ts?: boolean; argv?: string[]; env?: Record<string, string>; stdin?: string; allow?: string[]; timeoutMs?: number }; answer: { exit: number; stdout: string; stderr: string } };
  /** how many native coders, frames, solids and worlds are alive (for leak checks) */
  "media.live": { args: {}; answer: { vdecs: number; vencs: number; adecs: number; frames: number; solids: number; worlds: number } };
  /** bytes start..end of a file, base64 */
  "media.read": { args: { path: string; start: number; end: number }; answer: string };
  /** a file's size in bytes */
  "media.size": { args: { path: string }; answer: number };
  /** trim, scale and encode with sound to MP4, natively end to end */
  "media.transcode": { args: { path: string; out: string; from?: number; to?: number; height?: number; kbps?: number }; answer: { frames: number; width: number; height: number; fps: number; kbps: number; bytes: number } };
  /** base64 bytes written to a file */
  "media.write": { args: { path: string; data: string; truncate?: boolean; at?: number }; answer: null };
  /** an HTTP request under a policy (body base64 both ways) */
  "net.fetch": { args: { policy: number; url: string; method?: string; headers?: Record<string, string>; body?: string; followRedirects?: boolean; maxRedirects?: number; timeoutMs?: number }; answer: { status: number; statusText: string; headers: Record<string, string>; body: string; url: string; redirectChain: { status: number; statusText: string; headers: Record<string, string> }[] } };
  /** a network policy (allowed URL prefixes and methods; headers injected at the boundary, secrets from the host's environment) */
  "net.policy": { args: { allow: { prefix: string; methods?: string[]; headers?: Record<string, string>; secretHeaders?: Record<string, string> }[]; timeoutMs?: number; maxRedirects?: number; maxBytes?: number }; answer: { id: number } };
  /** one line of a headless run's output */
  "print": { args: { text: string }; answer: null };
  /** a boolean or hull of solids */
  "solid.combine": { args: { fn: "union" | "minus" | "intersect" | "hull"; ids: number[] }; answer: { id: number; expr: string } };
  /** a solid written as OBJ or glTF binary */
  "solid.export": { args: { id: number; path: string; format?: "obj" | "glb" }; answer: { bytes: number } };
  /** a Manifold solid from an expression (rdb's mesh shape language) */
  "solid.expr": { args: { expr: string }; answer: { id: number; expr: string } };
  /** a cross-section extruded: args height, divisions, twist degrees, top scale x, y */
  "solid.extrude": { args: { polygons: [number, number][][]; args: number[] }; answer: { id: number; expr: string } };
  /** drop a solid */
  "solid.free": { args: { id: number }; answer: null };
  /** a solid from closed triangles */
  "solid.from_mesh": { args: { verts: number[]; tris: number[] }; answer: { id: number; expr: string } };
  /** a solid read from OBJ or glTF binary */
  "solid.import": { args: { path: string }; answer: { id: number; expr: string } };
  /** the surface of an SDF sampled on a grid (negative inside) */
  "solid.level_set": { args: { grid: number[]; dims: [number, number, number]; min: [number, number, number]; max: [number, number, number]; level?: number; edge?: number }; answer: { id: number; expr: string } };
  /** a Manifold solid from a primitive */
  "solid.make": { args: { fn: "box" | "rounded_box" | "sphere" | "cylinder" | "cone" | "torus" | "text3d"; args: (number | string)[] }; answer: { id: number; expr: string } };
  /** a solid's triangles (positions x y z, indices by threes) */
  "solid.mesh": { args: { id: number }; answer: { verts: number[]; tris: number[] } };
  /** a solid translated, turned (degrees) or scaled */
  "solid.move": { args: { id: number; fn: "move" | "rotate" | "scale"; args: number[] }; answer: { id: number; expr: string } };
  /** a solid mirrored, transformed (3x4, by columns), trimmed by a plane, refined, smoothed, or Minkowski-summed/differenced with another */
  "solid.op": { args: { id: number; fn: "mirror" | "transform" | "trim" | "refine" | "smooth" | "minkowski" | "minkowski_diff"; args?: number[]; other?: number }; answer: { id: number; expr: string } };
  /** a solid's volume, bounds, triangle count, emptiness or cross-section at z */
  "solid.query": { args: { id: number; what: "volume" | "bounds" | "triangles" | "empty" | "slice" | "area" | "genus"; z?: number }; answer: number | boolean | { min: [number, number, number]; max: [number, number, number] } | { area: number; contours: number; polygons: [number, number][][] } };
  /** a cross-section revolved about y: args degrees, segments */
  "solid.revolve": { args: { polygons: [number, number][][]; args?: number[] }; answer: { id: number; expr: string } };
  /** SQL run by SQLite on a database file (or ":memory:") */
  "sqlite.exec": { args: { path: string; sql: string; readonly?: boolean }; answer: { sets: { columns: string[]; rows: (number | string | null | { blob: string })[][] }[]; error: string | null; changes: number } };
  /** tar on project files: create, extract (paths kept inside) or list, gzipped or not */
  "tar.run": { args: { root: string; cwd: string; create?: boolean; extract?: boolean; list?: boolean; gzip?: boolean; file: string; members?: string[]; dir?: string; verbose?: boolean }; answer: { stdout: string } };
  /** a URL parsed by the WHATWG rules (null when invalid) */
  "url.parse": { args: { url: string; base?: string }; answer: { href: string; origin: string; protocol: string; username: string; password: string; host: string; hostname: string; port: string; pathname: string; search: string; hash: string } | null };
  /** a URL with one part set, as the URL setters do (an invalid value leaves it unchanged) */
  "url.set": { args: { href: string; part: string; value: string }; answer: { href: string; origin: string; protocol: string; username: string; password: string; host: string; hostname: string; port: string; pathname: string; search: string; hash: string } };
  /** a packet decoded; the frames it completes */
  "vdec.decode": { args: { id: number; data: string; pts: number; dur: number }; answer: { frame: number; pts: number; dur: number; width: number; height: number }[] };
  /** the frames still held */
  "vdec.flush": { args: { id: number }; answer: { frame: number; pts: number; dur: number; width: number; height: number }[] };
  /** drop a decoder */
  "vdec.free": { args: { id: number }; answer: null };
  /** a VideoToolbox decoder for avc or hevc */
  "vdec.new": { args: { codec: string; description: string }; answer: { id: number } };
  /** the video codecs this machine encodes in hardware (VideoToolbox's list) */
  "venc.codecs": { args: {}; answer: { hardware: string[]; avc: boolean; hevc: boolean; av1: boolean; vp9: boolean } };
  /** an engine frame encoded */
  "venc.encode": { args: { id: number; frame: number; pts: number; dur: number }; answer: { packets: { data: string; key: boolean; pts: number; dur: number }[]; description: string | null } };
  /** the encoder flushed */
  "venc.finish": { args: { id: number }; answer: { packets: { data: string; key: boolean; pts: number; dur: number }[]; description: string | null } };
  /** a VideoToolbox H.264 encoder */
  "venc.new": { args: { width: number; height: number; fps: number; kbps: number }; answer: { id: number } };
  /** SHA-1, SHA-256, SHA-384 or SHA-512 of base64 bytes, base64 */
  "web.digest": { args: { algo: string; data: string }; answer: string };
  /** n random bytes (the OS's), base64 */
  "web.random": { args: { n: number }; answer: string };
  /** one WASI tool run in the project folder under fuel and memory limits */
  "wsx.run": { args: { tool: string; args: string[]; project?: string; fuel?: number; memMb?: number }; answer: { exit: number; stdout: string; stderr: string; fuel: number; ms: number; stopped: string | null } };
  /** the sandbox's WASI tools */
  "wsx.tools": { args: {}; answer: string[] };
  /** zlib (or raw) deflate, base64 */
  "zlib.deflate": { args: { data: string; level?: number; raw?: boolean }; answer: string };
  /** gzip (all members) inflated, base64 */
  "zlib.gunzip": { args: { data: string }; answer: string };
  /** base64 bytes gzipped (level 0-9, default 6), base64 */
  "zlib.gzip": { args: { data: string; level?: number }; answer: string };
  /** zlib (or raw) inflate, base64 */
  "zlib.inflate": { args: { data: string; raw?: boolean }; answer: string };
}

export type NativeName = keyof NativeCalls;
